; Sound update of each frame: crash sound and refuel tone, from $4880
; $4880-$48bf

; When jet_state bit 1 is set (the jet is on the landing pad), it plays the refuel tone. Otherwise it plays the extra-jet beep or the fuel alarm ($4fa0).
sound_update_landed
        lda jet_state
        and #$02
        beq sound_update_alarms
; Plays the refuel tone on voice 2: 4 frames on and 4 frames off. $25 counts the frames ($7c-$7f on, $fc-$ff off). $26 = 0 starts a new beep. At the end it sets $2e (GAS gauge colour) to 2.
refuel_tone
        lda refuel_sound_timer
        bmi refuel_tone_off_phase
        lda refuel_sound_step
        bne refuel_tone_on_step
        jsr refuel_tone_start           ; Starts a new beep. Its pitch follows the GAS digits.
refuel_tone_on_step
        inc refuel_sound_timer
        lda refuel_sound_timer
        bpl refuel_tone_done
        lda #$00
        sta refuel_sound_step
        lda #$fc                        ; $25 = $fc: four frames of silence follow.
        sta refuel_sound_timer
        bne refuel_tone_done
refuel_tone_off_phase
        lda refuel_sound_step
        bne refuel_tone_off_step
        lda #$14                        ; Voice 2: triangle and ring modulation, gate off.
        sta VCREG2
        inc refuel_sound_step
refuel_tone_off_step
        inc refuel_sound_timer
        lda refuel_sound_timer
        bmi refuel_tone_done
        lda #$00
        sta refuel_sound_step
        lda #$02
        sta gauge_colour
        bne refuel_tone_done
sound_update_alarms
        jsr extra_jet_beep
refuel_tone_done
        rts
